class Solution:
    def calPoints(self, operations: List[str]) -> int:
        stack = []
        n = len(operations)
        for i in range(n): 
            if operations[i] == 'D':
                stack.append(stack[-1] * 2)
            elif operations[i] == 'C':
                stack.pop()
            elif operations[i] == '+':
                stack.append(stack[-1] + stack[-2])
            else:
                stack.append(int(operations[i]))

        ans = 0
        for score in stack:
            ans += score
        return ans
